def R(y_orig, y_new):
    h_vals = np.array([0.1, 0.05, 0.025, 0.0125])
    err = np.abs(np.array([y_orig - 1.0, y_new - 1.0]))
    if err[0] == 0 or err[1] == 0:
        return False
    log_h = np.log(h_vals[:2])
    log_err = np.log(err)
    slope = (log_err[1] - log_err[0]) / (log_h[1] - log_h[0])
    return np.isclose(slope, 2.0, atol=0.2)
